import java.util.*;

public class Main {
    static class UnionFind {
        int[] parent;
        int[] size;
        int components;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            components = 0;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean unite(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) {
                return false;
            }
            if (size[x] < size[y]) {
                int temp = x;
                x = y;
                y = temp;
            }
            parent[y] = x;
            size[x] += size[y];
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007L;
        long result = 1;

        if (k == 0) {
            for (int i = 0; i < p - 1; i++) {
                result = (result * p) % MOD;
            }
        } else {
            UnionFind uf = new UnionFind(p);
            int cc = p;
            for (int i = 0; i < p; i++) {
                int to = (int)(((long)k * i) % p);
                if (uf.unite(i, to)) {
                    cc--;
                }
            }
            if (k > 1) {
                Set<Integer> comps = new HashSet<>();
                for (int i = 0; i < p; i++) {
                    comps.add(uf.find(i));
                }
                cc = comps.size();
            }
            for (int i = 0; i < cc; i++) {
                result = (result * p) % MOD;
            }
        }
        System.out.println(result);
        sc.close();
    }
}
